  if(j%4===0&&rand()<.7)block(xt+R(-.3,.3),yt-M(.2),zt+R(-.3,.3),M(R(.9,1.6)),M(R(.45,.8)),depth*R(.35,.6),Math.atan2(-dz,dx)+R(-.3,.3),.85,{base:pick(ruinPalette),natural:true});
